     1	"use client";
     2	
     3	import { Check, Circle, LoaderCircle } from "lucide-react";
     4	import Link from "next/link";
     5	import { useCallback, useEffect, useState } from "react";
     6	import { usePolling } from "@/lib/use-polling";
     7	import { Button } from "@/components/button";
     8	import { BankCredentialsForm, type BankCredentials } from "@/components/bank-credentials";
     9	
    10	type SyncImport = { id: string; status: string; total_rows: number; new_rows: number; matched_rows: number; review_rows: number; rejected_rows: number };
    11	type Connection = {
    12	  id: string; aspsp_name: string; aspsp_country: string; status: "active" | "expired" | "error";
    13	  valid_until: string | null; last_synced_at: string | null; sync_started_at: string | null; last_error: string | null;
    14	  accounts: { provider_account_uid: string; account_name: string; currency_code: string; last_booked_on: string | null }[];
    15	  sync: { running: boolean; imports: SyncImport[] };
    16	};
    17	type Bank = { name: string; country: string };
    18	
    19	const COUNTRIES = ["AT", "BE", "BG", "CY", "CZ", "DE", "DK", "EE", "ES", "FI", "FR", "GR", "HR", "HU", "IE", "IS", "IT", "LT", "LU", "LV", "MT", "NL", "NO", "PL", "PT", "RO", "SE", "SI", "SK"];
    20	const countryName = (code: string) => { try { return new Intl.DisplayNames(undefined, { type: "region" }).of(code) ?? code; } catch { return code; } };
    21	const RESULTS: Record<string, string> = {
    22	  connected: "Bank connected. The first sync is running and appears in import history.",
    23	  error: "The bank connection was cancelled or failed. Try again.",
    24	  invalid: "That bank link expired or was already used. Start the connection again.",
    25	};
    26	const day = 86_400_000;
    27	const REQUEST_GRACE_MS = 60_000;
    28	
    29	export function consentState(connection: Pick<Connection, "status" | "valid_until">, now = Date.now()): "expired" | "expiring" | null {
    30	  if (connection.status === "expired" || (connection.valid_until && Date.parse(connection.valid_until) <= now)) return "expired";
    31	  if (connection.valid_until && Date.parse(connection.valid_until) - now < 7 * day) return "expiring";
    32	  return null;
    33	}
    34	
    35	type StepState = "done" | "active" | "pending";
    36	const processedRows = (item: SyncImport) => item.new_rows + item.matched_rows + item.review_rows + item.rejected_rows;
    37	
    38	export function syncSteps(connection: Pick<Connection, "aspsp_name" | "sync">) {
    39	  const imports = connection.sync.imports;
    40	  const total = imports.reduce((sum, item) => sum + item.total_rows, 0);
    41	  const processed = imports.reduce((sum, item) => sum + Math.min(processedRows(item), item.total_rows), 0);
    42	  const importing = imports.some(item => item.status === "queued" || item.status === "running");
    43	  const fetched = imports.length > 0;
    44	  const state = (done: boolean, active: boolean): StepState => done ? "done" : active ? "active" : "pending";
    45	  return {
    46	    total, processed, importing,
    47	    steps: [
    48	      { label: fetched ? `Fetched ${total} transactions from ${connection.aspsp_name}` : `Asking ${connection.aspsp_name} for transactions and balance`, state: state(fetched, !fetched) },
    49	      { label: total ? `Importing ${processed} of ${total} rows` : "Import rows", state: state(fetched && !importing, importing) },
    50	      { label: "Updating balance and finishing up", state: state(false, fetched && !importing) },
    51	    ],
    52	  };
    53	}
    54	
    55	const elapsed = (from: string | null, now: number) => {
    56	  const seconds = from ? Math.max(0, Math.round((now - Date.parse(from)) / 1000)) : 0;
    57	  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
    58	};
    59	
    60	export function SyncProgress({ connection, now }: { connection: Pick<Connection, "aspsp_name" | "sync" | "sync_started_at">; now: number }) {
    61	  const { steps, total, processed, importing } = syncSteps(connection);
    62	  return <div className="space-y-3 rounded-lg border border-brand/40 bg-muted/40 p-3" role="status" aria-live="polite">
    63	    <div className="flex items-center justify-between gap-2 text-sm font-medium">
    64	      <span className="flex items-center gap-2"><LoaderCircle className="size-4 animate-spin text-brand" aria-hidden="true" />Syncing {connection.aspsp_name}</span>
    65	      <span className="text-xs font-normal tabular-nums text-muted-foreground">{elapsed(connection.sync_started_at, now)}</span>
    66	    </div>
    67	    <ol className="space-y-1.5 text-sm">{steps.map(step => <li key={step.label} className={`flex items-center gap-2 ${step.state === "pending" ? "text-muted-foreground" : ""}`}>
    68	      {step.state === "done" ? <Check className="size-4 shrink-0 text-brand" aria-label="Done" /> : step.state === "active" ? <LoaderCircle className="size-4 shrink-0 animate-spin" aria-label="In progress" /> : <Circle className="size-4 shrink-0" aria-label="Waiting" />}
    69	      {step.label}</li>)}</ol>
    70	    {importing && <progress className="h-2 w-full overflow-hidden rounded-full accent-brand" aria-label="Rows imported" max={Math.max(total, 1)} value={processed} />}
    71	    <p className="text-xs text-muted-foreground">You can leave this page; the sync keeps running and this updates when you come back.</p>
    72	  </div>;
    73	}
    74	
    75	export function syncSummary(connection: Pick<Connection, "sync" | "sync_started_at" | "last_synced_at">) {
    76	  const imports = connection.sync.imports;
    77	  if (!connection.sync_started_at || !connection.last_synced_at || Date.parse(connection.last_synced_at) < Date.parse(connection.sync_started_at)) return null;
    78	  if (!imports.length) return { text: "Last sync found no new transactions.", href: null };
    79	  const sum = (key: "new_rows" | "matched_rows" | "review_rows") => imports.reduce((total, item) => total + item[key], 0);
    80	  const review = sum("review_rows");
    81	  return { text: `Last sync: ${sum("new_rows")} new · ${sum("matched_rows")} already imported${review ? ` · ${review} need review` : ""}.`, href: `/import/${imports[imports.length - 1].id}/review` };
    82	}
    83	
    84	type ConnectionsData = { configured: boolean; credentials: BankCredentials; redirectUrl: string; connections: Connection[] };
    85	async function fetchConnections(): Promise<ConnectionsData> {
    86	  const response = await fetch("/api/bank/connections", { cache: "no-store" });
    87	  if (!response.ok) throw new Error("Connected banks are unavailable");
    88	  return response.json();
    89	}
    90	
    91	const date = (value: string | null) => value ? new Date(value).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" }) : "never";
    92	
    93	export function ConnectedBanks() {
    94	  const [data, setData] = useState<ConnectionsData | null>(null);
    95	  const [replacing, setReplacing] = useState(false);
    96	  const [message, setMessage] = useState<string | null>(null);
    97	  const [error, setError] = useState<string | null>(null);
    98	  const [busy, setBusy] = useState<string | null>(null);
    99	  const [country, setCountry] = useState("DE");
   100	  const [banks, setBanks] = useState<Bank[] | null>(null);
   101	  const [bank, setBank] = useState("");
   102	  const [requested, setRequested] = useState<Record<string, number>>({});
   103	
   104	  const load = useCallback(() => fetchConnections().then(setData, () => setError("Connected banks are unavailable.")), []);
   105	  useEffect(() => {
   106	    let live = true;
   107	    fetchConnections().then(loaded => {
   108	      if (!live) return;
   109	      setData(loaded);
   110	      const region = navigator.language.split("-")[1]?.toUpperCase();
   111	      if (region && COUNTRIES.includes(region)) setCountry(region);
   112	      const result = new URLSearchParams(window.location.search).get("bank");
   113	      if (result && RESULTS[result]) setMessage(RESULTS[result]);
   114	      if (result === "connected" && loaded.connections[0]) setRequested({ [loaded.connections[0].id]: Date.now() });
   115	    }, () => { if (live) setError("Connected banks are unavailable."); });
   116	    return () => { live = false; };
   117	  }, []);
   118	
   119	  const [now, setNow] = useState(() => Date.now());
   120	  const running = (connection: Connection) => connection.sync.running || (now - (requested[connection.id] ?? 0) < REQUEST_GRACE_MS
   121	    && (!connection.last_synced_at || Date.parse(connection.last_synced_at) < requested[connection.id]));
   122	  const syncing = !!data?.connections.some(running);
   123	  usePolling(() => { setNow(Date.now()); return fetchConnections().then(setData, () => undefined); }, 2000, syncing);
   124	
   125	  async function act(key: string, run: () => Promise<Response>, done?: string) {
   126	    setBusy(key); setError(null); setMessage(null);
   127	    try {
   128	      const response = await run();
   129	      const body = await response.json().catch(() => ({}));
   130	      if (!response.ok) throw new Error(body.error ?? "Something went wrong");
   131	      if (body.url) { window.location.assign(body.url); return; }
   132	      if (done) setMessage(done);
   133	      await load();
   134	    } catch (failure) {
   135	      setError(failure instanceof Error ? failure.message : "Something went wrong");
   136	      setBusy(null);
   137	      return false;
   138	    }
   139	    setBusy(null);
   140	    return true;
   141	  }
   142	  const connect = (aspspName: string, aspspCountry: string) => act(`connect:${aspspName}`, () => fetch("/api/bank/connect", {
   143	    method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ aspspName, country: aspspCountry }) }));
   144	  async function loadBanks() {
   145	    setBusy("banks"); setError(null); setBanks(null); setBank("");
   146	    try {
   147	      const response = await fetch(`/api/bank/aspsps?country=${country}`);
   148	      const body = await response.json().catch(() => ({}));
   149	      if (response.ok) { setBanks(body.banks); if (!body.banks.length) setError(`Enable Banking has no banks for ${countryName(country)}. You can still import statements from your bank.`); } else setError(body.error ?? "Banks could not be loaded");
   150	    } catch { setError("Banks could not be loaded. Check your connection and try again."); }
   151	    finally { setBusy(null); }
   152	  }
   153	
   154	  return <section aria-labelledby="connected-banks" className="scroll-mt-20 space-y-4 rounded-xl border border-border bg-card p-6">
   155	    <div>
   156	      <h2 id="connected-banks" className="text-sm font-medium">Connected banks</h2>
   157	      <p className="mt-1 text-sm text-muted-foreground">Sync booked transactions and balances through Enable Banking. Each sync is an ordinary import you can review, and undo if nothing depends on it.</p>
   158	    </div>
   159	    {message && <p role="status" className="text-sm text-foreground">{message}</p>}
   160	    {error && <p role="alert" className="text-sm text-danger">{error}</p>}
   161	    {!data ? (error ? <Button variant="outline" className="min-h-10" onClick={() => { setError(null); void load(); }}>Try again</Button> : <p className="text-sm text-muted-foreground">Loading…</p>) : <>
   162	      {data.connections.length > 0 && <ul className="space-y-3">{data.connections.map(connection => {
   163	        const consent = consentState(connection);
   164	        return <li key={connection.id} className="space-y-3 rounded-lg border border-border p-4">
   165	          {consent && <div role="alert" className="flex flex-wrap items-center justify-between gap-2 rounded-md border border-warning/40 bg-warning-soft px-3 py-2 text-sm text-warning">
   166	            <span>{consent === "expired" ? "Bank consent has ended. Reconnect to keep syncing." : `Bank consent ends ${date(connection.valid_until)}. Reconnect to keep syncing.`}</span>
   167	            <Button size="sm" disabled={!!busy || !data.configured} onClick={() => void connect(connection.aspsp_name, connection.aspsp_country)}>Reconnect</Button>
   168	          </div>}
   169	          <div className="flex flex-wrap items-start justify-between gap-3">
   170	            <div className="min-w-0">
   171	              <h3 className="font-medium">{connection.aspsp_name} <span className="text-xs font-normal text-muted-foreground">{connection.aspsp_country}</span></h3>
   172	              <p className="text-xs text-muted-foreground">Last sync {date(connection.last_synced_at)} · consent until {date(connection.valid_until)}</p>
   173	            </div>
   174	            <div className="flex gap-2">
   175	              <Button size="sm" variant="outline" disabled={!!busy || connection.status !== "active" || !data.configured}
   176	                onClick={() => { const at = Date.now(); setNow(at); setRequested(current => ({ ...current, [connection.id]: at }));
   177	                  void act(`sync:${connection.id}`, () => fetch(`/api/bank/connections/${connection.id}/sync`, { method: "POST" }))
   178	                    .then(ok => { if (!ok) setRequested(current => { const next = { ...current }; delete next[connection.id]; return next; }); }); }}>
   179	                {busy === `sync:${connection.id}` ? "Starting…" : running(connection) ? "Syncing…" : "Sync now"}</Button>
   180	              <Button size="sm" variant="ghost" disabled={!!busy}
   181	                onClick={() => { if (window.confirm(`Disconnect ${connection.aspsp_name}? Imported transactions stay; undo imports separately.`))
   182	                  void act(`delete:${connection.id}`, () => fetch(`/api/bank/connections/${connection.id}`, { method: "DELETE" }), "Bank disconnected."); }}>
   183	                {busy === `delete:${connection.id}` ? "Disconnecting…" : "Disconnect"}</Button>
   184	            </div>
   185	          </div>
   186	          {running(connection) ? <SyncProgress connection={connection} now={now} /> : (() => {
   187	            const summary = syncSummary(connection);
   188	            return summary && <p className="text-sm text-muted-foreground">{summary.text}{summary.href && <> <Link href={summary.href} className="text-brand underline-offset-4 hover:underline">Review rows</Link></>}</p>;
   189	          })()}
   190	          {connection.last_error && <p className="text-sm text-warning">{connection.last_error}</p>}
   191	          <ul className="divide-y divide-border text-sm">{connection.accounts.map(account => <li key={account.provider_account_uid} className="flex justify-between gap-3 py-1.5">
   192	            <span className="truncate">{account.account_name}</span>
   193	            <span className="shrink-0 text-muted-foreground">{account.currency_code} · {account.last_booked_on ? `through ${account.last_booked_on}` : "not synced yet"}</span>
   194	          </li>)}</ul>
   195	        </li>;
   196	      })}</ul>}
   197	      {!data.configured || replacing ? <BankCredentialsForm redirectUrl={data.redirectUrl} onCancel={replacing ? () => setReplacing(false) : undefined}
   198	        onSaved={() => { setReplacing(false); setMessage("Enable Banking is set up. Choose your bank to connect it."); void load(); }} /> : <>
   199	      <div className="flex flex-wrap items-end gap-3">
   200	        <label className="grid gap-1.5 text-sm font-medium">Country
   201	          <select value={country} onChange={event => { setCountry(event.target.value); setBanks(null); }} className="min-h-10 rounded-lg border border-border bg-card px-3 py-2 text-sm font-normal">
   202	            {COUNTRIES.map(code => [code, countryName(code)]).sort((a, b) => a[1].localeCompare(b[1])).map(([code, name]) => <option key={code} value={code}>{name}</option>)}</select></label>
   203	        {banks ? <>
   204	          <label className="grid min-w-56 flex-1 gap-1.5 text-sm font-medium">Bank
   205	            <select value={bank} onChange={event => setBank(event.target.value)} className="min-h-10 rounded-lg border border-border bg-card px-3 py-2 text-sm font-normal">
   206	              <option value="">Choose your bank</option>{banks.map(item => <option key={item.name}>{item.name}</option>)}</select></label>
   207	          <Button className="min-h-10" disabled={!bank || !!busy} onClick={() => void connect(bank, country)}>{busy?.startsWith("connect:") ? "Opening bank…" : "Connect bank"}</Button>
   208	          <p className="basis-full text-xs text-muted-foreground">Your bank&apos;s login opens in the browser. Some banks ask you to approve twice: once for access and once for history older than 90 days.</p>
   209	        </> : <Button variant="outline" className="min-h-10" disabled={!!busy} onClick={() => void loadBanks()}>{busy === "banks" ? "Loading banks…" : "Choose a bank"}</Button>}
   210	      </div>
   211	      <p className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
   212	        <span>Enable Banking app{data.credentials.hint ? ` ending in ${data.credentials.hint}` : ""}{data.credentials.source === "env" ? ", read from .env or a system environment variable" : ""}</span>
   213	        <button type="button" disabled={!!busy} className="underline-offset-4 hover:text-foreground hover:underline" onClick={() => setReplacing(true)}>Replace</button>
   214	        {data.credentials.source === "app" && <button type="button" disabled={!!busy} className="underline-offset-4 hover:text-foreground hover:underline"
   215	          onClick={() => { if (window.confirm("Remove the Enable Banking App ID and key? Connected banks and imported transactions stay, but syncing stops until you add them again."))
   216	            void act("credentials", () => fetch("/api/bank/credentials", { method: "DELETE" }), "Enable Banking App ID and key removed."); }}>Remove</button>}
   217	      </p></>}
   218	    </>}
   219	  </section>;
   220	}
